<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { useList } from '../useList'
import { date } from '../api'
import { useAuth } from '../auth'
import LoadError from '../components/LoadError.vue'
import StateTag from '../components/StateTag.vue'
const auth=useAuth(),list=useList('/logs',false),instances=useList('/instances'),page=ref(1),selected=ref<any>(null),range=ref<string[]>([])
const form=reactive({status:'',tool_name:'',client_name:'',instance_id:'',user_id:'',token_id:''})
function load(reset=false){if(reset)page.value=1;const q=new URLSearchParams({limit:'20',offset:String(Math.max(0,page.value-1)*20)});for(const[k,v]of Object.entries(form))if(v)q.set(k,v);if(range.value?.length===2){q.set('from',new Date(range.value[0]!).toISOString());q.set('to',new Date(range.value[1]!).toISOString())}list.load('?'+q)}
function name(id:string){return instances.items.value.find(x=>x.id===id)?.name||id||'—'}
onMounted(()=>load())
</script>
<template><section class="panel"><div class="panel-toolbar"><div><h2>{{auth.personal?'本机调用记录':auth.admin?'组织调用记录':'我的调用记录'}}</h2><p>{{auth.admin?'可查看组织全部记录；':'仅显示归属于当前账号的记录；'}}用户归属由 Gateway Token 确定，服务归属由 MCP 实例确定。参数和结果正文不保存。</p></div><el-button :loading="list.loading.value" @click="load()">刷新</el-button></div><div class="filter-bar wrap"><el-select v-model="form.status" placeholder="全部结果" clearable><el-option v-for="[value,label] in [['succeeded','成功'],['failed','失败'],['rejected','拒绝'],['unknown','结果未知'],['limited','限流'],['accepted','处理中']]" :key="value" :value="value" :label="label"/></el-select><el-select v-model="form.instance_id" placeholder="全部实例" clearable filterable><el-option v-for="i in instances.items.value" :key="i.id" :label="i.name" :value="i.id"/></el-select><el-input v-model="form.tool_name" placeholder="工具名称" clearable/><el-input v-model="form.client_name" placeholder="客户端名称" clearable/><el-input v-if="auth.admin&&!auth.personal" v-model="form.user_id" placeholder="用户 ID" clearable/><el-input v-model="form.token_id" placeholder="Token ID" clearable/><el-date-picker v-model="range" type="datetimerange" start-placeholder="开始时间" end-placeholder="结束时间"/><el-button type="primary" @click="load(true)">筛选</el-button></div><LoadError :error="list.error.value" @retry="load()"/><el-table :data="list.items.value" v-loading="list.loading.value" @row-click="selected=$event"><el-table-column label="调用时间" min-width="180"><template #default="{row}">{{date(row.created_at)}}</template></el-table-column><el-table-column prop="tool_name" label="工具" min-width="170" show-overflow-tooltip/><el-table-column label="MCP 实例" min-width="150" show-overflow-tooltip><template #default="{row}">{{name(row.instance_id)}}</template></el-table-column><el-table-column prop="client_name" label="客户端" min-width="130"/><el-table-column label="结果" width="110"><template #default="{row}"><StateTag :value="row.status"/></template></el-table-column><el-table-column label="耗时" width="100"><template #default="{row}">{{row.duration_ms??0}} ms</template></el-table-column><el-table-column label="详情" width="80"><template #default="{row}"><el-button text @click.stop="selected=row">查看</el-button></template></el-table-column><template #empty><el-empty description="暂无符合条件的调用记录"/></template></el-table><div class="pagination"><el-pagination v-model:current-page="page" :page-size="20" :total="list.total.value" layout="total, prev, pager, next" @current-change="load()"/></div></section><el-drawer :model-value="!!selected" @close="selected=null" title="调用详情" size="500px"><el-descriptions v-if="selected" :column="1" border><el-descriptions-item label="请求 ID"><code>{{selected.id}}</code></el-descriptions-item><el-descriptions-item label="结果"><StateTag :value="selected.status"/></el-descriptions-item><el-descriptions-item label="时间">{{date(selected.created_at)}}</el-descriptions-item><el-descriptions-item label="用户">{{selected.user_id||'未认证'}}</el-descriptions-item><el-descriptions-item label="Token ID"><code>{{selected.token_id||'—'}}</code></el-descriptions-item><el-descriptions-item label="实例 ID"><code>{{selected.instance_id||'—'}}</code></el-descriptions-item><el-descriptions-item label="客户端">{{selected.client_name||'—'}}</el-descriptions-item><el-descriptions-item label="MCP">{{name(selected.instance_id)}}</el-descriptions-item><el-descriptions-item label="工具">{{selected.tool_name}}</el-descriptions-item><el-descriptions-item label="耗时">{{selected.duration_ms}} ms</el-descriptions-item><el-descriptions-item label="诊断摘要">{{selected.detail||'无'}}</el-descriptions-item></el-descriptions></el-drawer></template>
